-- Synthetic grants and all writes below roll back.
BEGIN;
DO $test$
DECLARE org uuid:=current_setting('test.organisation_id')::uuid;actor uuid:=current_setting('test.actor_id')::uuid;client uuid;job uuid;otherjob uuid;grant_id uuid;var uuid;question uuid;response uuid;conv uuid;doc uuid;photo uuid;record uuid;hash text:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');request uuid:=gen_random_uuid();payload jsonb;result jsonb;stamp timestamptz;photo_stamp timestamptz;declined_var uuid;decline_data jsonb;failed boolean;before_access public.billing_access_state;
BEGIN
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 client:=public.client_portal_manage(org,gen_random_uuid(),'create_client','{"name":"Portal workflow rollback client","type":"individual"}');
 EXECUTE 'RESET ROLE';
 INSERT INTO public.jobs(organisation_id,client_id,reference,project_name) VALUES(org,client,'PORTAL-WORKFLOW-ROLLBACK','Portal workflow project') RETURNING id INTO job;
 INSERT INTO public.jobs(organisation_id,reference,project_name) VALUES(org,'PORTAL-WORKFLOW-OTHER','Other project') RETURNING id INTO otherjob;
 EXECUTE 'SET LOCAL ROLE authenticated';
 payload:=jsonb_build_object('client_id',client,'email','portal-workflow@example.invalid','hours',24,'token_hash',hash,'job_ids',jsonb_build_array(job),'permissions',jsonb_build_array('progress','schedule','variations','decisions','financials','documents','photos','messages'));
 grant_id:=public.client_portal_manage(org,request,'create_link',payload);
 IF public.client_portal_manage(org,request,'create_link',payload)<>grant_id THEN RAISE EXCEPTION 'Link retry duplicated grant';END IF;
 failed:=false;BEGIN PERFORM public.client_portal_manage(org,gen_random_uuid(),'create_link',payload||jsonb_build_object('token_hash',repeat('2',64),'job_ids',jsonb_build_array(otherjob)));EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Unowned job grant accepted';END IF;
 EXECUTE 'RESET ROLE';
 INSERT INTO public.variations(organisation_id,job_id,reference,title,client_price_pence,vat_pence,total_pence,status) VALUES(org,job,'PORTAL-WORKFLOW-V','Client decision',10000,2000,12000,'sent') RETURNING id,updated_at INTO var,stamp;
 INSERT INTO public.project_documents(organisation_id,job_id,name,category,bucket,object_path,original_filename,mime_type,visibility) VALUES(org,job,'Shared contract','contract','job-documents',org||'/'||job||'/contract.pdf','contract.pdf','application/pdf','client_visible') RETURNING id INTO doc;
 INSERT INTO public.evidence_records(organisation_id,job_id,evidence_type,caption,visibility,review_status) VALUES(org,job,'photo','Shared accepted photo','client_visible','accepted') RETURNING id INTO record;
 INSERT INTO public.evidence_files(organisation_id,evidence_id,bucket,object_path,original_filename,mime_type,visibility) VALUES(org,record,'job-evidence',org||'/'||job||'/'||record||'/photo.jpg','photo.jpg','image/jpeg','client_visible') RETURNING id INTO photo;
 EXECUTE 'SET LOCAL ROLE service_role';
 result:=public.client_portal_overview(hash);
 IF NOT(result->>'can_respond')::boolean OR NOT(result->>'can_message')::boolean OR jsonb_array_length(result->'documents')<>1 OR jsonb_array_length(result->'photos')<>1 THEN RAISE EXCEPTION 'Portal capabilities or files missing';END IF;
 IF public.client_portal_asset(hash,'document',doc)->>'filename'<>'contract.pdf' OR public.client_portal_asset(hash,'photo',photo)->>'filename'<>'photo.jpg' THEN RAISE EXCEPTION 'Shared file authorisation failed';END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM public.client_portal_manage(org,gen_random_uuid(),'set_document_visibility',jsonb_build_object('id',doc,'version',1,'expected_visibility','client_visible','visibility','internal_only'));
 EXECUTE 'SET LOCAL ROLE service_role';
 failed:=false;BEGIN PERFORM public.client_portal_asset(hash,'document',doc);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Hidden document downloaded';END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM public.client_portal_manage(org,gen_random_uuid(),'set_document_visibility',jsonb_build_object('id',doc,'version',1,'expected_visibility','internal_only','visibility','client_visible'));
 failed:=false;BEGIN PERFORM public.client_portal_manage(org,gen_random_uuid(),'set_document_visibility',jsonb_build_object('id',doc,'version',0,'expected_visibility','client_visible','visibility','internal_only'));EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Stale sharing accepted';END IF;
 SELECT updated_at INTO photo_stamp FROM public.evidence_records WHERE id=record;
 PERFORM public.client_portal_manage(org,gen_random_uuid(),'set_photo_visibility',jsonb_build_object('id',photo,'record_updated_at',photo_stamp,'expected_visibility','client_visible','visibility','internal_only'));
 EXECUTE 'SET LOCAL ROLE service_role';
 failed:=false;BEGIN PERFORM public.client_portal_asset(hash,'photo',photo);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Internal evidence file signed';END IF;
 UPDATE public.evidence_files SET visibility='client_visible' WHERE id=photo;
 UPDATE public.project_documents SET object_path='foreign/'||job||'/contract.pdf' WHERE id=doc;
 failed:=false;BEGIN PERFORM public.client_portal_asset(hash,'document',doc);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Cross-tenant storage path signed';END IF;
 UPDATE public.project_documents SET object_path=org||'/'||job||'/contract.pdf' WHERE id=doc;
 payload:=jsonb_build_object('variation_id',var,'version',1,'updated_at',stamp,'total_pence',12000,'currency','GBP','name','Test Client','message','Please explain this price');request:=gen_random_uuid();
 question:=public.client_portal_write(hash,request,'question',payload);
 IF public.client_portal_write(hash,request,'question',payload)<>question OR (SELECT count(*) FROM public.variation_responses WHERE variation_id=var)<>1 THEN RAISE EXCEPTION 'Question replay duplicated';END IF;
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'approved',payload||'{"price_confirmed":true,"authority_confirmed":true}');EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Stale timestamp approved';END IF;
 SELECT updated_at INTO stamp FROM public.variations WHERE id=var;payload:=payload||jsonb_build_object('updated_at',stamp,'price_confirmed',true,'authority_confirmed',true);
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'approved',payload||'{"total_pence":100}');EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Stale price approved';END IF;
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'approved',payload||'{"authority_confirmed":false}');EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'No authority confirmation accepted';END IF;
 EXECUTE 'RESET ROLE';UPDATE public.organisations SET default_currency='EUR' WHERE id=org;EXECUTE 'SET LOCAL ROLE service_role';
 IF (SELECT currency FROM public.variations WHERE id=var)<>'GBP' THEN RAISE EXCEPTION 'Record currency changed with company settings';END IF;
 request:=gen_random_uuid();response:=public.client_portal_write(hash,request,'approved',payload);
 IF public.client_portal_write(hash,request,'approved',payload)<>response OR NOT EXISTS(SELECT 1 FROM public.variations WHERE id=var AND status='approved') OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE entity_id=var AND action='client_variation_approved' AND change_summary->>'total_pence'='12000') THEN RAISE EXCEPTION 'Approval or audit incorrect';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.variation_responses WHERE id=response AND reviewed_snapshot->>'currency'='GBP' AND reviewed_snapshot->>'total_pence'='12000') THEN RAISE EXCEPTION 'Reviewed snapshot missing';END IF;
 failed:=false;BEGIN UPDATE public.variations SET title='Changed after approval',total_pence=1 WHERE id=var;EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Approved terms changed silently';END IF;
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'declined',payload);EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Final decision overwritten';END IF;
 request:=gen_random_uuid();payload:=jsonb_build_object('job_id',job,'name','Test Client','message','Please call me');response:=public.client_portal_write(hash,request,'message',payload);
 IF public.client_portal_write(hash,request,'message',payload)<>response THEN RAISE EXCEPTION 'Message replay duplicated';END IF;
 SELECT conversation_id INTO conv FROM public.messages WHERE id=response;
 IF jsonb_array_length(public.client_portal_overview(hash)->'messages')<>1 THEN RAISE EXCEPTION 'Client message not visible';END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.client_portal_inbox(org);IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result) r WHERE r->>'id'=response::text) THEN RAISE EXCEPTION 'Client message absent from contractor inbox';END IF;
 PERFORM public.client_portal_manage(org,gen_random_uuid(),'reply_message',jsonb_build_object('conversation_id',conv,'message','We will call this afternoon'));
 EXECUTE 'SET LOCAL ROLE service_role';
 IF jsonb_array_length(public.client_portal_overview(hash)->'messages')<>2 OR jsonb_array_length(public.client_portal_overview(hash)->'responses')<>2 THEN RAISE EXCEPTION 'Reply or decision history missing';END IF;
 UPDATE public.variations SET current_version=2,status='draft',title='Private revised proposal' WHERE id=var;
 IF jsonb_array_length(public.client_portal_overview(hash)->'variations')<>0 OR jsonb_array_length(public.client_portal_overview(hash)->'responses')<>2 THEN RAISE EXCEPTION 'New draft exposed or old decision history lost';END IF;
 failed:=false;BEGIN UPDATE public.variations SET current_version=1,status='approved' WHERE id=var;EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Signed version rolled backwards';END IF;
 INSERT INTO public.variations(organisation_id,job_id,reference,title,client_price_pence,total_pence,status,approval_deadline) VALUES(org,job,'PORTAL-WORKFLOW-DECLINE','Decline test',100,100,'sent',CURRENT_DATE-1) RETURNING id,updated_at INTO declined_var,stamp;
 decline_data:=jsonb_build_object('variation_id',declined_var,'version',1,'updated_at',stamp,'total_pence',100,'currency','EUR','name','Test Client','message','Not required','price_confirmed',true,'authority_confirmed',true);
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'approved',decline_data);EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Expired offer approved';END IF;
 PERFORM public.client_portal_write(hash,gen_random_uuid(),'declined',decline_data);
 IF NOT EXISTS(SELECT 1 FROM public.variations WHERE id=declined_var AND status='declined') THEN RAISE EXCEPTION 'Decline not saved';END IF;
 UPDATE public.portal_access SET permissions=ARRAY['progress'] WHERE id=grant_id;
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'message',payload);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Messaging permission bypass';END IF;
 failed:=false;BEGIN PERFORM public.client_portal_asset(hash,'document',doc);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'File permission bypass';END IF;
 UPDATE public.portal_access SET permissions=ARRAY['progress','messages'] WHERE id=grant_id;
 EXECUTE 'RESET ROLE';SELECT access_state INTO before_access FROM public.organisation_subscriptions WHERE organisation_id=org;UPDATE public.organisation_subscriptions SET access_state='read_only' WHERE organisation_id=org;
 EXECUTE 'SET LOCAL ROLE service_role';
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'message',payload);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Read-only portal write accepted';END IF;
 IF (public.client_portal_overview(hash)->>'can_message')::boolean THEN RAISE EXCEPTION 'Read-only capabilities wrong';END IF;
 EXECUTE 'RESET ROLE';UPDATE public.organisation_subscriptions SET access_state=before_access WHERE organisation_id=org;
 -- The original access state is restored before the remaining checks and the whole transaction rolls back.
 EXECUTE 'SET LOCAL ROLE authenticated';
 failed:=false;BEGIN PERFORM public.client_portal_manage(org,gen_random_uuid(),'revoke_link',jsonb_build_object('access_id',grant_id,'revision',0,'reason','Stale'));EXCEPTION WHEN OTHERS THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Stale revocation accepted';END IF;
 EXECUTE 'RESET ROLE';UPDATE public.organisation_members SET role='finance' WHERE organisation_id=org AND user_id=actor;EXECUTE 'SET LOCAL ROLE authenticated';
 failed:=false;BEGIN PERFORM public.client_portal_manage(org,gen_random_uuid(),'revoke_link',jsonb_build_object('access_id',grant_id,'revision',1,'reason','Forbidden'));EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Finance revoked client access';END IF;
 EXECUTE 'RESET ROLE';UPDATE public.organisation_members SET role='owner' WHERE organisation_id=org AND user_id=actor;EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM public.client_portal_manage(org,gen_random_uuid(),'revoke_link',jsonb_build_object('access_id',grant_id,'revision',1,'reason','Testing revoke'));
 EXECUTE 'SET LOCAL ROLE service_role';
 failed:=false;BEGIN PERFORM public.client_portal_write(hash,gen_random_uuid(),'message',payload);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Revoked grant wrote message';END IF;
 failed:=false;BEGIN PERFORM public.client_portal_asset(hash,'document',doc);EXCEPTION WHEN insufficient_privilege THEN failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Revoked grant downloaded file';END IF;
 IF has_function_privilege('anon','public.client_portal_write(text,uuid,text,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.client_portal_asset(text,text,uuid)','EXECUTE') OR has_table_privilege('authenticated','public.portal_access','INSERT') OR has_table_privilege('authenticated','public.variation_responses','INSERT') THEN RAISE EXCEPTION 'Direct capability bypass';END IF;
END $test$;
RESET ROLE;
ROLLBACK;
